"""Module 02 concepts: the operational amplifier (Floyd 9e Ch.12; Jaeger Ch.10-11 parts)."""
from lib import K
M = 'm02'
K('m02-ideal-practical', M, ('Op-amp lý tưởng và thực tế', 'Ideal and practical op-amps'),
  ('Op-amp là bộ khuếch đại vi sai có một ngõ ra, hai ngõ vào (đảo − và không đảo +), nguồn đối xứng ±V và độ lợi vòng hở rất lớn. Mạch ngoài (điện trở) mới quyết định độ lợi thực dùng.', 'An op-amp is a differential amplifier with one output, an inverting (−) and a noninverting (+) input, a dual ±V supply and a very large open-loop gain. External resistors set the gain actually used.'),
  facts=[('Lý tưởng: Zin = ∞, Zout = 0, Aol = ∞, BW = ∞, CMRR = ∞', ('Hai quy tắc: không có dòng vào; V₊ = V₋ khi có hồi tiếp âm.', 'Two rules: no input current; V₊ = V₋ with negative feedback.')), ('Thực tế (bảng bài giảng): Aol 10⁵–2·10⁵; Zin ≈ MΩ–GΩ; Zout ≈ 10–100 Ω; CMRR ≳ 90 dB', ('Giá trị điển hình, đọc datasheet cho linh kiện cụ thể.', 'Typical values; read the datasheet for a specific part.'))],
  steps=[('Dùng mô hình lý tưởng để tính độ lợi vòng kín; chỉ dùng thông số thực khi đề hỏi sai số hoặc giới hạn.', 'Use the ideal model for the closed-loop gain; use real parameters only when the question asks about errors or limits.')],
  traps=[('Coi Aol là độ lợi dùng thực tế: Aol rất lớn nhưng không ổn định, độ lợi do mạch ngoài đặt.', 'Treating Aol as the working gain: it is huge but unstable; the external network sets the gain.')],
  angles=[('Liệt kê thông số lý tưởng của op-amp.', 'List the ideal op-amp parameters.'), ('So sánh Zin, Zout, Aol lý tưởng và thực tế.', 'Compare ideal and practical Zin, Zout, Aol.')],
  topics=['Op-amp basics'], kw=['op-amp', 'operational amplifier', 'open-loop gain', 'ideal', 'input impedance', 'output impedance', 'virtual ground', 'inverting input', 'noninverting input'], kwv=['op-amp', 'khuếch đại thuật toán', 'độ lợi vòng hở', 'lý tưởng', 'trở kháng vào', 'trở kháng ra', 'đất ảo'],
  src=['Floyd 9e §12–1'], related=['m02-modes-cmrr', 'm02-feedback-gain'], chk='idealmodel')
K('m02-modes-cmrr', M, ('Chế độ ngõ vào và CMRR', 'Input modes and CMRR'),
  ('Vi sai ngõ vào đơn (một ngõ nối đất), vi sai kép (tín hiệu giữa hai ngõ) và chế độ chung (cùng tín hiệu ở cả hai ngõ). CMRR đo khả năng triệt tín hiệu chung.', 'Single-ended differential (one input grounded), double-ended differential (signal between the inputs) and common mode (the same signal on both). CMRR measures how well the common-mode signal is rejected.'),
  facts=[('Vout = Aol·(V₊ − V₋) + Acm·V_cm', ('Độ lợi vi sai và chung.', 'Differential and common-mode gain.')), ('CMRR = Aol/Acm ,  CMRR(dB) = 20·log₁₀(Aol/Acm)', ('CMRR càng lớn càng tốt.', 'The larger the CMRR the better.'))],
  steps=[('Tính tỉ số Aol/Acm rồi đổi sang dB bằng 20·log₁₀.', 'Compute Aol/Acm and convert to dB with 20·log₁₀.'), ('Đổi ngược: Aol/Acm = 10^(dB/20).', 'Convert back: Aol/Acm = 10^(dB/20).')],
  traps=[('Dùng 10·log₁₀ thay vì 20·log₁₀ cho tỉ số điện áp.', 'Using 10·log₁₀ instead of 20·log₁₀ for a voltage ratio.'), ('Quên nhiễu giống nhau trên hai dây bị triệt, không phải khuếch đại.', 'Forgetting that noise common to both wires is rejected, not amplified.')],
  angles=[('Tính CMRR (dB) từ Aol và Acm.', 'Compute CMRR (dB) from Aol and Acm.'), ('Mức nhiễu chung ở ngõ ra khi biết CMRR.', 'Common-mode output level given the CMRR.')],
  topics=['Input modes and CMRR'], kw=['cmrr', 'common mode', 'common-mode rejection', 'differential', 'single-ended', 'double-ended', 'common-mode gain', 'acm', 'rejection ratio'], kwv=['cmrr', 'chế độ chung', 'vi sai', 'triệt tín hiệu chung', 'nhiễu chung', 'độ lợi chung'],
  src=['Floyd 9e §12–2'], related=['m02-ideal-practical', 'm05-instrumentation'], chk='cmrr')
K('m02-bias-offset', M, ('Dòng phân cực, offset và bù', 'Bias current, offset and compensation'),
  ('Hai ngõ vào luôn hút một dòng nhỏ; nếu hai dòng khác nhau hoặc tầng vào lệch, ngõ ra có sai số một chiều. Điện trở bù ở ngõ (+) triệt sai số do dòng phân cực.', 'Both inputs always draw a small current; if the two differ or the input stage is unbalanced, the output carries a dc error. A compensating resistor at the (+) input cancels the bias-current error.'),
  facts=[('I_BIAS = (I₁ + I₂)/2 ,  I_OS = |I₁ − I₂|', ('Dòng phân cực trung bình và dòng offset.', 'Average bias current and offset current.')), ('V_OS: áp vào làm ngõ ra = 0', ('Do lệch cân bằng tầng vào.', 'Caused by input-stage imbalance.')), ('Rc = Ri‖Rf = Ri·Rf/(Ri + Rf)', ('Điện trở bù đặt ở ngõ (+).', 'Compensating resistor placed at the (+) input.'))],
  steps=[('Tính trung bình để ra I_BIAS, hiệu để ra I_OS (giá trị tuyệt đối).', 'Average for I_BIAS, difference for I_OS (absolute value).'), ('Chọn Rc bằng điện trở tương đương nhìn từ ngõ (−) để hai ngõ có cùng sụt áp.', 'Choose Rc equal to the resistance seen from the (−) input so both inputs see the same drop.')],
  traps=[('Nhầm I_OS (hiệu) với I_BIAS (trung bình).', 'Mixing I_OS (difference) with I_BIAS (average).'), ('Đặt Rc ở ngõ sai hoặc quên song song Ri với Rf.', 'Putting Rc on the wrong input or forgetting Ri‖Rf.')],
  angles=[('Cho I₁ và I₂, tính I_BIAS và I_OS.', 'Given I₁ and I₂, find I_BIAS and I_OS.'), ('Chọn giá trị điện trở bù cho mạch đảo.', 'Pick the compensating resistor for an inverting stage.')],
  topics=['Offset, bias and slew rate', 'Impedances and compensation'], kw=['bias current', 'offset', 'input offset', 'offset current', 'offset voltage', 'compensating resistor', 'i_bias', 'vos', 'null'], kwv=['dòng phân cực', 'offset', 'dòng lệch', 'điện áp lệch', 'điện trở bù', 'cân bằng'],
  src=['Floyd 9e §12–2'], related=['m02-slew-rate', 'm03-summing'], chk='bias')
K('m02-slew-rate', M, ('Slew rate và tần số tối đa không méo', 'Slew rate and the maximum undistorted frequency'),
  ('Slew rate (SR) là tốc độ đổi lớn nhất của ngõ ra, đơn vị V/μs. Tín hiệu lớn, tần số cao bị giới hạn bởi SR và méo thành dạng tam giác.', 'The slew rate (SR) is the maximum rate of change of the output, in V/μs. Large high-frequency signals are limited by SR and distort into a triangular shape.'),
  facts=[('SR = ΔVout/Δt', ('Thời gian đổi mức: Δt = ΔV/SR.', 'Time to change level: Δt = ΔV/SR.')), ('f_max = SR/(2π·Vp)', ('Tần số lớn nhất của sin biên độ đỉnh Vp mà không méo.', 'Highest frequency of a sine of peak Vp without distortion.'))],
  steps=[('Đổi μs ↔ ms trước khi chia.', 'Convert μs ↔ ms before dividing.'), ('Kiểm: SR yêu cầu = 2π·f·Vp so với SR của linh kiện.', 'Check: required SR = 2π·f·Vp against the device SR.')],
  traps=[('Chỉ kiểm băng thông mà quên slew rate: tín hiệu “đủ băng thông” vẫn có thể méo.', 'Checking only bandwidth and forgetting slew rate: a signal “within bandwidth” can still distort.'), ('Sai đơn vị μs/ms.', 'Unit slips between μs and ms.')],
  angles=[('Đổi −10 V → +10 V với SR cho trước mất bao lâu?', 'How long does −10 V → +10 V take at a given SR?'), ('Tần số sin lớn nhất không méo ở 10 V đỉnh.', 'Highest undistorted sine frequency at 10 V peak.')],
  topics=['Offset, bias and slew rate'], kw=['slew rate', 'v/μs', 'v/us', 'distortion', 'maximum frequency', 'full power', 'rise time'], kwv=['slew rate', 'tốc độ quay', 'méo', 'tần số tối đa', 'thời gian đổi mức'],
  src=['Floyd 9e §12–2'], related=['m02-frequency'], chk='slew')
K('m02-feedback-gain', M, ('Hồi tiếp âm và độ lợi vòng kín', 'Negative feedback and closed-loop gain'),
  ('Hồi tiếp âm đưa một phần B của ngõ ra về ngõ vào đảo. Độ lợi vòng kín chủ yếu do mạch hồi tiếp đặt: Acl ≈ 1/B khi B·Aol ≫ 1.', 'Negative feedback returns a fraction B of the output to the inverting input. The closed-loop gain is set mainly by the feedback network: Acl ≈ 1/B when B·Aol ≫ 1.'),
  facts=[('Acl = Aol/(1 + B·Aol) → 1/B khi B·Aol ≫ 1', ('Công thức chính xác và gần đúng.', 'Exact and approximate form.')), ('B = Ri/(Ri + Rf) (mạch không đảo)', ('Hệ số hồi tiếp.', 'Feedback fraction.'))],
  steps=[('Tính B từ mạng điện trở.', 'Compute B from the resistor network.'), ('Tính Acl chính xác nếu đề cho Aol hữu hạn; nếu không dùng 1/B.', 'Use the exact Acl if Aol is finite; otherwise 1/B.')],
  traps=[('Bỏ “1 +” trong công thức không đảo.', 'Dropping the “1 +” in the noninverting formula.'), ('Dùng 1/B khi B·Aol không đủ lớn.', 'Using 1/B when B·Aol is not large enough.')],
  angles=[('Tính Acl chính xác với Aol = 100 000 và B cho trước.', 'Compute the exact Acl for Aol = 100,000 and a given B.'), ('Hồi tiếp âm đổi Zin, Zout, băng thông thế nào?', 'How does negative feedback change Zin, Zout and bandwidth?')],
  topics=['Negative feedback and gain'], kw=['negative feedback', 'closed-loop gain', 'feedback fraction', 'acl', 'attenuation', 'loop gain', 'feedback'], kwv=['hồi tiếp âm', 'độ lợi vòng kín', 'hệ số hồi tiếp', 'hồi tiếp'],
  src=['Floyd 9e §12–3'], related=['m02-noninverting', 'm02-inverting', 'm04-feedback'], chk='feedback')
K('m02-noninverting', M, ('Mạch khuếch đại không đảo', 'Noninverting amplifier'),
  ('Tín hiệu vào ngõ (+), một phần ngõ ra B = Ri/(Ri + Rf) về ngõ (−). Ngõ ra cùng pha với ngõ vào và Zin rất lớn.', 'The signal enters the (+) input and a fraction B = Ri/(Ri + Rf) of the output returns to (−). The output is in phase with the input and Zin is very large.'),
  facts=[('Acl(NI) = 1 + Rf/Ri', ('Luôn ≥ 1.', 'Always ≥ 1.')), ('Vout = Acl·Vin', ('Cùng dấu với Vin.', 'Same sign as Vin.'))],
  steps=[('Nhận dạng: tín hiệu vào ngõ (+), Rf nối ngõ ra với (−), Ri nối (−) với đất.', 'Recognise: signal on (+), Rf from output to (−), Ri from (−) to ground.'), ('Tính 1 + Rf/Ri rồi nhân với Vin.', 'Compute 1 + Rf/Ri and multiply by Vin.'), ('Thiết kế: Rf/Ri = Acl − 1.', 'Design: Rf/Ri = Acl − 1.')],
  traps=[('Dùng −Rf/Ri của mạch đảo.', 'Using the inverting −Rf/Ri.'), ('Chọn Acl < 1: không thể với mạch này.', 'Choosing Acl < 1: not possible with this circuit.')],
  angles=[('Ri = 10 kΩ, Rf = 220 kΩ: độ lợi và ngõ ra với 50 mV?', 'Ri = 10 kΩ, Rf = 220 kΩ: gain and output for 50 mV?'), ('Tìm Rf để có độ lợi 25.', 'Find Rf for a gain of 25.')],
  topics=['Negative feedback and gain'], kw=['noninverting amplifier', 'non-inverting', 'noninverting', 'gain of 1 +', 'in phase', 'rf/ri'], kwv=['mạch không đảo', 'khuếch đại không đảo', 'không đảo', 'cùng pha'],
  src=['Floyd 9e §12–4'], related=['m02-inverting', 'm02-follower', 'm02-feedback-gain'], chk='noninv')
K('m02-inverting', M, ('Mạch khuếch đại đảo và đất ảo', 'Inverting amplifier and the virtual ground'),
  ('Tín hiệu vào qua Ri tới ngõ (−), ngõ (+) nối đất. Ngõ (−) là “đất ảo” nên dòng qua Ri bằng dòng qua Rf; ngõ ra ngược pha và Zin ≈ Ri.', 'The signal goes through Ri to the (−) input while (+) is grounded. The (−) input is a “virtual ground”, so the current through Ri equals the current through Rf; the output is inverted and Zin ≈ Ri.'),
  facts=[('Acl(I) = −Rf/Ri', ('Dấu − là đảo pha.', 'The minus sign is the phase inversion.')), ('Zin ≈ Ri ,  Zout ≈ Zout/(1 + B·Aol)', ('Zin thấp hơn mạch không đảo.', 'Zin is much lower than the noninverting circuit.'))],
  steps=[('Đất ảo: V₋ ≈ 0, nên I = Vin/Ri.', 'Virtual ground: V₋ ≈ 0, so I = Vin/Ri.'), ('Dòng đó chảy qua Rf: Vout = −I·Rf.', 'That current flows through Rf: Vout = −I·Rf.')],
  traps=[('Quên dấu âm của ngõ ra.', 'Forgetting the minus sign of the output.'), ('Dùng Ri + Rf làm trở kháng vào: Zin ≈ Ri.', 'Using Ri + Rf as the input impedance: Zin ≈ Ri.')],
  angles=[('Ri = 10 kΩ, Rf = 220 kΩ, vin = 50 mV: ngõ ra?', 'Ri = 10 kΩ, Rf = 220 kΩ, vin = 50 mV: output?'), ('Vì sao Zin của mạch đảo nhỏ?', 'Why is the inverting circuit\'s Zin low?')],
  topics=['Negative feedback and gain'], kw=['inverting amplifier', 'virtual ground', 'virtual short', 'phase inversion', '-rf/ri'], kwv=['mạch đảo', 'khuếch đại đảo', 'đất ảo', 'đảo pha'],
  src=['Floyd 9e §12–4'], related=['m02-noninverting', 'm03-summing'], chk='inv')
K('m02-follower', M, ('Mạch lặp điện áp (đệm)', 'Voltage follower (buffer)'),
  ('Ngõ ra nối thẳng về ngõ (−): Acl = 1, cùng pha, Zin cực lớn, Zout cực nhỏ, dùng làm mạch đệm.', 'The output is wired straight to the (−) input: Acl = 1, in phase, a huge Zin and a tiny Zout; used as a buffer.'),
  facts=[('Acl = 1', ('Trường hợp riêng của mạch không đảo với Rf = 0.', 'The noninverting circuit with Rf = 0.')), ('Zin = (1 + Aol)·Zin(op-amp) ,  Zout = Zout/(1 + Aol)', ('B = 1.', 'B = 1.'))],
  steps=[('Dùng khi nguồn có trở kháng cao hoặc tải nặng.', 'Use it when the source impedance is high or the load is heavy.')],
  traps=[('Cho rằng mạch lặp không có tác dụng vì độ lợi bằng 1: tác dụng ở trở kháng.', 'Thinking the follower is useless because its gain is 1: its value is in the impedances.')],
  angles=[('Độ lợi và trở kháng của mạch lặp điện áp.', 'Gain and impedances of the voltage follower.')],
  topics=['Negative feedback and gain', 'Impedances and compensation'], kw=['voltage follower', 'unity gain', 'buffer', 'follower', 'isolate'], kwv=['mạch lặp', 'lặp điện áp', 'đệm', 'độ lợi đơn vị'],
  src=['Floyd 9e §12–5'], related=['m02-noninverting', 'm02-impedances'], chk='follower')
K('m02-impedances', M, ('Ảnh hưởng của hồi tiếp lên Zin và Zout', 'Effect of feedback on Zin and Zout'),
  ('Hồi tiếp âm làm mạch “cứng” hơn: ở mạch không đảo Zin tăng và Zout giảm đúng hệ số (1 + B·Aol).', 'Negative feedback makes the circuit “stiffer”: in the noninverting circuit Zin rises and Zout falls by exactly the factor (1 + B·Aol).'),
  facts=[('Zin(NI) = (1 + B·Aol)·Zin ,  Zout(NI) = Zout/(1 + B·Aol)', ('Mạch không đảo.', 'Noninverting circuit.')), ('Zin(I) ≈ Ri ,  Zout(I) = Zout/(1 + B·Aol)', ('Mạch đảo.', 'Inverting circuit.'))],
  steps=[('Tính 1 + B·Aol trước rồi nhân/chia Zin, Zout.', 'Compute 1 + B·Aol first, then multiply/divide Zin and Zout.'), ('Đổi đơn vị Ω ↔ MΩ ↔ GΩ cẩn thận.', 'Handle Ω ↔ MΩ ↔ GΩ carefully.')],
  traps=[('Áp công thức mạch không đảo cho mạch đảo.', 'Applying the noninverting formula to the inverting circuit.')],
  angles=[('Aol = 100 000, B = 1/101, Zin = 2 MΩ: Zin(NI)?', 'Aol = 100,000, B = 1/101, Zin = 2 MΩ: Zin(NI)?'), ('Zout sau hồi tiếp với Zout = 75 Ω.', 'Zout after feedback for Zout = 75 Ω.')],
  topics=['Impedances and compensation'], kw=['input impedance', 'output impedance', 'zin', 'zout', 'stiffer', 'impedance with feedback'], kwv=['trở kháng vào', 'trở kháng ra', 'ảnh hưởng của hồi tiếp'],
  src=['Floyd 9e §12–4'], related=['m02-feedback-gain', 'm02-follower'], chk='impedance')
K('m02-frequency', M, ('Đáp ứng tần số, băng thông và tích GBW', 'Frequency response, bandwidth and the gain–bandwidth product'),
  ('Aol giảm theo tần số như một mạch RC thông thấp; hồi tiếp đổi độ lợi lấy băng thông: độ lợi × băng thông vòng kín là hằng số f_T.', 'Aol falls with frequency like an RC low-pass; feedback trades gain for bandwidth: closed-loop gain × bandwidth is the constant f_T.'),
  facts=[('Aol = Aol(mid)/√(1 + (f/fc)²) ,  θ = −tan⁻¹(f/fc)', ('Tại fc độ lợi giảm còn 0,707 (−3 dB), pha −45°.', 'At fc the gain falls to 0.707 (−3 dB), phase −45°.')), ('fc(cl) = fc(ol)·(1 + B·Aol(mid))', ('Băng thông vòng kín.', 'Closed-loop bandwidth.')), ('f_T = Acl·fc(cl) = Aol(mid)·fc(ol)', ('Tần số độ lợi đơn vị.', 'Unity-gain frequency.'))],
  steps=[('Tính f_T từ Aol(mid) và fc(ol), rồi fc(cl) = f_T/Acl.', 'Compute f_T from Aol(mid) and fc(ol), then fc(cl) = f_T/Acl.'), ('Độ lợi dB giảm 3 dB tại fc.', 'The dB gain is 3 dB down at fc.')],
  traps=[('Quên rằng độ lợi lớn hơn thì băng thông hẹp hơn.', 'Forgetting that more gain means less bandwidth.'), ('Lẫn fc(ol) rất nhỏ (Hz–kHz) với f_T (MHz).', 'Confusing the tiny fc(ol) (Hz–kHz) with f_T (MHz).')],
  angles=[('GBW = 1 MHz: băng thông ở độ lợi 20?', 'GBW = 1 MHz: bandwidth at a gain of 20?'), ('Độ lợi giảm bao nhiêu dB tại tần số cắt?', 'By how many dB does the gain fall at the cutoff?')],
  topics=['Frequency response and bandwidth'], kw=['bandwidth', 'gain-bandwidth', 'unity-gain frequency', 'cutoff frequency', 'frequency response', 'roll-off', 'gbw', 'ft', '3 db', 'decibel'], kwv=['băng thông', 'tần số cắt', 'đáp ứng tần số', 'tích độ lợi băng thông', 'tần số độ lợi đơn vị', 'decibel'],
  src=['Floyd 9e §12–3'], related=['m02-slew-rate', 'm06-poles'], chk='frequency')
